exercises.solutionCode:
/* 客户端 TCP 状态 */
typedef enum {
    TCP_CLOSED = 0,
    TCP_SYN_SENT,
    TCP_ESTABLISHED,
    TCP_FIN_WAIT_1,
    TCP_FIN_WAIT_2,
    TCP_TIME_WAIT
} TcpState;

/* 驱动状态机的事件 */
typedef enum {
    EV_CONNECT = 0,
    EV_RECV_SYN_ACK,
    EV_CLOSE,
    EV_RECV_ACK,
    EV_RECV_FIN,
    EV_TIMEOUT
} TcpEvent;

int tcp_client_step(int state, int event)
{
    if (state < TCP_CLOSED || state > TCP_TIME_WAIT) {
        return -1;
    }
    if (event < EV_CONNECT || event > EV_TIMEOUT) {
        return -1;
    }

    switch (state) {
    case TCP_CLOSED:
        if (event == EV_CONNECT) {
            return TCP_SYN_SENT;
        }
        break;
    case TCP_SYN_SENT:
        if (event == EV_RECV_SYN_ACK) {
            return TCP_ESTABLISHED;   /* 客户端回 ACK 后连接建立 */
        }
        break;
    case TCP_ESTABLISHED:
        if (event == EV_CLOSE) {
            return TCP_FIN_WAIT_1;    /* 发送 FIN，等待对方 ACK */
        }
        break;
    case TCP_FIN_WAIT_1:
        if (event == EV_RECV_ACK) {
            return TCP_FIN_WAIT_2;    /* 收到 ACK，等待对方 FIN */
        }
        break;
    case TCP_FIN_WAIT_2:
        if (event == EV_RECV_FIN) {
            return TCP_TIME_WAIT;     /* 收到 FIN，进入 TIME_WAIT */
        }
        break;
    case TCP_TIME_WAIT:
        if (event == EV_TIMEOUT) {
            return TCP_CLOSED;        /* 等待超时后资源才被释放 */
        }
        break;
    default:
        break;
    }

    return -1;   /* 其余组合均为非法迁移 */
}
